function Login({ data, login, go, online }: { data: DemoState; login: (s: Session, to?: string) => void; go: (p: string) => void; online: boolean }) {
  const [mode, setMode] = useState<'whatsapp' | 'email'>('whatsapp')
  const [step, setStep] = useState<'contact' | 'otp'>('contact')
  const [contact, setContact] = useState('')
  const [otp, setOtp] = useState('')
  const [error, setError] = useState('')
  const [sentBy, setSentBy] = useState<'whatsapp' | 'sms' | 'email'>('whatsapp')
  function send(e: FormEvent) { e.preventDefault(); if (!online) return; setError(''); setSentBy(mode); setStep('otp') }
  function verify(e: FormEvent) {
    e.preventDefault()
    if (otp !== DEMO_OTP) return setError('Código incorreto. Neste protótipo, use 123456.')
    const found = data.members.find(m => mode === 'email' ? m.email.toLowerCase() === contact.trim().toLowerCase() : onlyDigits(m.phone) === onlyDigits(contact))
    if (!found) return setError('Associado não encontrado. Use ana@exemplo.com ou 81999990001.')
    login({ role: 'member', memberId: found.id })
  }
  return <div className="auth-layout"><div className="auth-aside"><button className="brand-button" onClick={() => go('/')}><Brand dark /></button><div><Eyebrow>SEU ESPAÇO DE CUIDADO</Eyebrow><h1>Bom ter você<br /><em>de volta.</em></h1><p>Seu cartão e seus benefícios estão esperando por você.</p></div><div className="auth-art-card"><span>✳ RKMED</span><b>Um jeito melhor<br />de cuidar.</b><small>LINHA GOLD</small></div></div><main className="auth-main"><div className="auth-card"><span className="auth-topline">ÁREA DO ASSOCIADO <span>01 / 02</span></span><h2>Entre na sua conta</h2><p>Escolha como prefere receber seu código de acesso.</p><div className="auth-tabs"><button className={mode === 'whatsapp' ? 'active' : ''} onClick={() => { setMode('whatsapp'); setStep('contact'); setError('') }}><Smartphone size={17} /> Login com whatsapp</button><button className={mode === 'email' ? 'active' : ''} onClick={() => { setMode('email'); setStep('contact'); setError('') }}><Mail size={17} /> Login com email</button></div>{step === 'contact' ? <form onSubmit={send}><label className="field-label">{mode === 'email' ? 'Seu e-mail' : 'Seu WhatsApp'}<input className="input" type={mode === 'email' ? 'email' : 'tel'} required placeholder={mode === 'email' ? 'ana@exemplo.com' : '(81) 99999-0001'} value={contact} onChange={e => setContact(e.target.value)} /></label><p className="helper">{mode === 'whatsapp' ? 'Enviamos pelo WhatsApp. Se necessário, usamos SMS como alternativa.' : 'Enviamos um código temporário para seu e-mail verificado.'}</p><Button type="submit" disabled={!online} className="full">Continuar <ArrowRight size={18} /></Button></form> : <form onSubmit={verify}><button type="button" className="back-link" onClick={() => setStep('contact')}><ArrowLeft size={15} /> Alterar contato</button><label className="field-label">Código recebido por {sentBy === 'email' ? 'e-mail' : sentBy === 'sms' ? 'SMS' : 'WhatsApp'}<input className="input otp-input" inputMode="numeric" maxLength={6} required placeholder="••••••" value={otp} onChange={e => setOtp(onlyDigits(e.target.value))} /></label><Button type="submit" disabled={!online} className="full">Acessar meu cartão <ArrowRight size={18} /></Button><button type="button" className="text-link" onClick={() => { setSentBy('sms'); setError('Código enviado por SMS (simulado).') }}>Não chegou? {mode === 'whatsapp' ? 'Tentar por SMS' : 'Reenviar e-mail'}</button></form>}{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<div className="demo-hint"><Sparkles size={16} /><span><b>Acesso de demonstração</b><br />WhatsApp: 81999990001 · E-mail: ana@exemplo.com · Código: <b>123456</b></span></div><p className="auth-foot">Ainda não faz parte? <button onClick={() => go('/cadastro')}>Comece aqui <ArrowRight size={14} /></button></p></div></main></div>
}

function StaffLogin({ role, login, go }: { role: 'partner' | 'admin'; login: (s: Session, to?: string) => void; go: (p: string) => void }) {
  const [email, setEmail] = useState(role === 'partner' ? 'parceiro@rkmed.demo' : 'admin@rkmed.demo')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  function submit(e: FormEvent) {
    e.preventDefault()
    const allowed = role === 'partner' ? email === 'parceiro@rkmed.demo' : ['admin@rkmed.demo', 'diretoria@rkmed.demo'].includes(email)
    if (!allowed || password !== DEMO_PASSWORD) return setError('Credenciais de demonstração inválidas.')
    login({ role: email === 'diretoria@rkmed.demo' ? 'viewer' : role })
  }
  return <div className="staff-login"><button className="brand-button" onClick={() => go('/')}><Brand /></button><div className="staff-login-card"><span className="auth-topline">{role === 'partner' ? 'ACESSO DO ESTABELECIMENTO' : 'ACESSO DA EQUIPE RK'}</span><div className="staff-login-icon">{role === 'partner' ? <ScanLine size={25} /> : <ShieldCheck size={25} />}</div><h1>{role === 'partner' ? 'Painel do parceiro' : 'Painel de gestão'}</h1><p>{role === 'partner' ? 'Valide associados e registre compras com segurança.' : 'Acompanhe a operação e cuide de cada detalhe.'}</p><form onSubmit={submit}><label className="field-label">E-mail<input className="input" type="email" value={email} onChange={e => setEmail(e.target.value)} required /></label><label className="field-label">Senha<input className="input" type="password" placeholder="••••••••" value={password} onChange={e => setPassword(e.target.value)} required /></label>{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<Button type="submit" className="full">Entrar <ArrowRight size={17} /></Button></form><div className="demo-hint"><Sparkles size={16} /><span><b>Dados de demonstração</b><br />{role === 'partner' ? 'parceiro@rkmed.demo' : 'admin@rkmed.demo ou diretoria@rkmed.demo'}<br />Senha: <b>{DEMO_PASSWORD}</b>{role === 'partner' && <> · Funcionário: <b>{DEMO_EMPLOYEE_CODE}</b></>}</span></div></div></div>
}

type AppShared = { data: DemoState; update: (d: DemoState) => void; session: Session | null; login: (s: Session, to?: string) => void; go: (p: string) => void; online: boolean; notify: (m: string) => void }

function Enrollment({ data, update, login, go, online }: AppShared) {
  const [step, setStep] = useState(1)
  const [form, setForm] = useState({ name: '', cpf: '', birth: '', email: '', phone: '' })
  const [emailOtp, setEmailOtp] = useState('')
  const [phoneOtp, setPhoneOtp] = useState('')
  const [photo, setPhoto] = useState('')
  const [faceStatus, setFaceStatus] = useState<'idle' | 'checking' | 'approved' | 'rejected'>('idle')
  const [cameraOpen, setCameraOpen] = useState(false)
  const [error, setError] = useState('')
  const [accept, setAccept] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)
  function set<K extends keyof typeof form>(key: K, value: typeof form[K]) { setForm(prev => ({ ...prev, [key]: value })) }
  function nextFirst(e: FormEvent) {
    e.preventDefault(); setError('')
    if (!validCpf(form.cpf)) return setError('CPF inválido. Confira os números digitados.')
    if (!isAdult(form.birth)) return setError('A associação individual é para maiores de 18 anos.')
    if (data.members.some(m => m.cpf === onlyDigits(form.cpf))) return setError('CPF já cadastrado. Entre pelo acesso de associado.')
    if (onlyDigits(form.phone).length < 10) return setError('Informe um celular com DDD.')
    setStep(2)
  }
  async function onPhoto(file?: File) {
    if (!file) return
    setError(''); setFaceStatus('checking'); setPhoto('')
    try {
      const result = await detectFace(file)
      if (result.count !== 1) { setFaceStatus('rejected'); return setError(result.count === 0 ? 'Nenhum rosto detectado. Use uma foto nítida, de frente e bem iluminada.' : 'Encontramos mais de um rosto. Use uma foto apenas sua.') }
      setPhoto(result.preview); setFaceStatus('approved')
    } catch (cause) { setFaceStatus('rejected'); setError(cause instanceof Error ? cause.message : 'Não foi possível analisar a foto.') }
  }
  function verify(e: FormEvent) {
    e.preventDefault(); setError('')
    if (emailOtp !== DEMO_OTP || phoneOtp !== DEMO_OTP) return setError('Confirme os dois códigos. Neste protótipo, ambos são 123456.')
    if (!photo || faceStatus !== 'approved') return setError('Adicione uma foto com um rosto detectado.')
    if (!accept) return setError('Confirme o aceite dos textos de teste para continuar.')
    const m: Member = { id: `member-${Date.now()}`, name: form.name.trim(), cpf: onlyDigits(form.cpf), email: form.email.toLowerCase(), phone: onlyDigits(form.phone), cardToken: `RKMED-GOLD-${crypto.randomUUID().toUpperCase()}`, status: 'active', photo, joinedAt: new Date().toISOString(), paidThrough: new Date(Date.now() + 30 * 86400000).toISOString(), emailVerified: true, phoneVerified: true }
    update({ ...data, members: [...data.members, m] }); setStep(4)
    window.setTimeout(() => login({ role: 'member', memberId: m.id }), 1700)
  }
  return <div className="enroll"><header className="simple-header shell"><button className="brand-button" onClick={() => go('/')}><Brand /></button><button className="back-link" onClick={() => step === 1 ? go('/') : setStep(step - 1)}><ArrowLeft size={16} /> Voltar</button></header><div className="enroll-shell"><div className="enroll-head"><Eyebrow>FAÇA PARTE DA LINHA GOLD</Eyebrow><h1>Seu cuidado começa <em>aqui.</em></h1><p>Alguns passos para ter seus benefícios sempre à mão.</p><div className="step-progress">{['Seus dados', 'Sua foto', 'Confirmação'].map((label, i) => <div className={step > i + 1 ? 'done' : step === i + 1 ? 'current' : ''} key={label}><span>{step > i + 1 ? <Check size={13} /> : i + 1}</span><small>{label}</small></div>)}</div></div><div className="enroll-card">{step === 1 && <form onSubmit={nextFirst}><span className="form-step">PASSO 01 DE 03</span><h2>Prazer, vamos nos conhecer.</h2><p>Precisamos apenas do essencial para criar seu cartão.</p><div className="form-grid"><label className="field-label wide">Nome completo<input className="input" value={form.name} onChange={e => set('name', e.target.value)} required placeholder="Como está no seu documento" /></label><label className="field-label">CPF<input className="input" value={form.cpf} onChange={e => set('cpf', e.target.value)} required inputMode="numeric" maxLength={14} placeholder="000.000.000-00" /></label><label className="field-label">Data de nascimento<input className="input" type="date" value={form.birth} onChange={e => set('birth', e.target.value)} required /></label><label className="field-label">E-mail<input className="input" type="email" value={form.email} onChange={e => set('email', e.target.value)} required placeholder="seu@email.com" /></label><label className="field-label">WhatsApp<input className="input" type="tel" value={form.phone} onChange={e => set('phone', e.target.value)} required placeholder="(81) 99999-9999" /></label></div>{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<Button type="submit" className="full">Continuar <ArrowRight size={17} /></Button></form>}{step === 2 && <div><span className="form-step">PASSO 02 DE 03</span><h2>Uma foto para reconhecer você.</h2><p>O parceiro confere visualmente sua foto no balcão. Aqui detectamos apenas se existe um rosto na imagem.</p><div className="photo-actions"><Button type="button" onClick={() => { setError(''); setCameraOpen(true) }}><Camera size={17} /> Usar câmera</Button><Button type="button" variant="secondary" onClick={() => inputRef.current?.click()}>Escolher foto</Button></div>{cameraOpen ? <LiveFaceCamera onCapture={file => { setCameraOpen(false); void onPhoto(file) }} onClose={() => setCameraOpen(false)} /> : <div className="photo-uploader" onClick={() => inputRef.current?.click()} role="button" tabIndex={0} onKeyDown={e => e.key === 'Enter' && inputRef.current?.click()}>{photo ? <img src={photo} alt="Prévia da sua foto" /> : <div className="upload-placeholder"><div><Camera size={25} /></div><b>Escolha uma foto sua</b><span>De frente, com boa luz e sem outras pessoas</span><small>JPG, PNG ou HEIC · até 5 MB</small></div>}{faceStatus === 'checking' && <span className="photo-overlay"><RefreshCw className="spin" /> Analisando rosto...</span>}</div>}<input ref={inputRef} hidden type="file" accept="image/jpeg,image/png,image/heic,image/heif" onChange={e => { void onPhoto(e.target.files?.[0]); e.target.value = '' }} />{faceStatus === 'approved' && <div className="inline-success"><CheckCircle2 size={17} /> Um rosto detectado. A foto pode seguir para o cadastro.</div>}{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<Button onClick={() => { setError(''); setStep(3) }} disabled={!photo || faceStatus !== 'approved' || cameraOpen} className="full">Continuar <ArrowRight size={17} /></Button><p className="tiny-note"><ShieldCheck size={15} /> Detecção de rosto não confirma identidade.</p></div>}{step === 3 && <form onSubmit={verify}><span className="form-step">PASSO 03 DE 03</span><h2>Confirme seus contatos.</h2><p>Na primeira adesão, confirme e-mail e telefone. Em acessos futuros, um deles será suficiente.</p><div className="verification-card"><Mail size={21} /><span><b>E-mail</b><small>{form.email}</small></span><BadgeCheck size={18} /></div><label className="field-label">Código enviado por e-mail<input className="input" value={emailOtp} inputMode="numeric" maxLength={6} onChange={e => setEmailOtp(onlyDigits(e.target.value))} placeholder="000000" required /></label><div className="verification-card"><Smartphone size={21} /><span><b>WhatsApp</b><small>{form.phone} · SMS se necessário</small></span><BadgeCheck size={18} /></div><label className="field-label">Código enviado por WhatsApp<input className="input" value={phoneOtp} inputMode="numeric" maxLength={6} onChange={e => setPhoneOtp(onlyDigits(e.target.value))} placeholder="000000" required /></label><div className="demo-hint"><Sparkles size={16} /><span>Para demonstrar, use <b>123456 nos dois campos</b>. Nenhuma mensagem real é enviada.</span></div><label className="check-row"><input type="checkbox" checked={accept} onChange={e => setAccept(e.target.checked)} /><span>Li os <button type="button" onClick={() => go('/termos')}>termos</button> e o <button type="button" onClick={() => go('/privacidade')}>aviso de privacidade</button> de teste.</span></label><div className="legal-warning">{LEGAL_WARNING}</div>{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<Button type="submit" disabled={!online} className="full">Finalizar cadastro de demonstração <ArrowRight size={17} /></Button><p className="tiny-note">Pagamento Stripe simulado nesta versão visual. Assinatura demonstrativa de {brl(6960)}/mês.</p></form>}{step === 4 && <div className="enroll-done"><div><Check size={34} /></div><h2>Você chegou!</h2><p>Seu cartão digital de demonstração está pronto.</p><Button onClick={() => go('/app')}>Ver meu cartão <ArrowRight size={17} /></Button></div>}</div></div></div>
}

function QrDisplay({ token }: { token: string }) {
  const [url, setUrl] = useState('')
  useEffect(() => { let alive = true; void import('qrcode').then(({ default: QRCode }) => QRCode.toDataURL(token, { margin: 1, width: 440, color: { dark: '#17241e', light: '#ffffff' } })).then(value => { if (alive) setUrl(value) }); return () => { alive = false } }, [token])
  return url ? <img className="qr-img" src={url} alt="QR do cartão do associado" /> : <div className="qr-loading"><RefreshCw className="spin" /></div>
}

function MemberApp({ data, member, path, go, logout, online, notify }: AppShared & { member: Member; path: string; logout: () => void }) {
  const [filter, setFilter] = useState('Todos')
  const [query, setQuery] = useState('')
  const [showMenu, setShowMenu] = useState(false)
  const [accountAction, setAccountAction] = useState<'billing' | 'support' | null>(null)
  const saved = memberSavings(member.id, data.purchases)
  const myPurchases = data.purchases.filter(p => p.memberId === member.id).sort((a, b) => b.createdAt.localeCompare(a.createdAt))
  const available = data.partners.filter(p => (filter === 'Todos' || p.segment === filter) && p.name.toLowerCase().includes(query.toLowerCase()))
  const tabs = [{ to: '/app', icon: <Home size={19} />, label: 'Início' }, { to: '/app/parceiros', icon: <MapPin size={19} />, label: 'Parceiros' }, { to: '/app/economia', icon: <Wallet size={19} />, label: 'Economia' }, { to: '/app/conta', icon: <UserRound size={19} />, label: 'Conta' }]
  const section = path.split('/')[2] ?? ''
  return <div className="member-app"><aside className="member-sidebar"><Brand /><nav>{tabs.map(t => <button key={t.to} className={path === t.to ? 'selected' : ''} onClick={() => go(t.to)}>{t.icon}{t.label}</button>)}</nav><div className="sidebar-help"><div><Heart size={19} /></div><b>Cuidar de você<br />faz bem.</b><small>Seu clube, seu tempo.</small></div><button className="logout-link" onClick={logout}><LogOut size={18} /> Sair da conta</button></aside><div className="member-content"><header className="member-topbar"><Brand /><div><span className="sync-status">{online ? <Wifi size={14} /> : <WifiOff size={14} />}{online ? 'Conectado' : 'Modo offline'}</span><button className="avatar-button" onClick={() => setShowMenu(!showMenu)}><Avatar member={member} size="tiny" /><span>{member.name.split(' ')[0]}</span><ChevronDown size={15} /></button>{showMenu && <div className="profile-menu"><button onClick={() => go('/app/conta')}>Minha conta</button><button onClick={logout}>Sair</button></div>}</div></header><div className="member-main">{!section && <><div className="welcome-row"><div><Eyebrow>BEM-VINDA À LINHA GOLD</Eyebrow><h1>Olá, {member.name.split(' ')[0]} <span>✳</span></h1><p>Seu cuidado começa com boas escolhas. Seu cartão está pronto para acompanhar você.</p></div><div className="date-chip"><CalendarDays size={17} /> {new Intl.DateTimeFormat('pt-BR', { day: 'numeric', month: 'long' }).format(new Date())}</div></div><div className="member-overview"><div className="member-card-block"><div className="digital-card"><div className="digital-card-top"><Brand dark /><span>MEMBRO GOLD</span></div><div className="digital-card-center"><span>Seu cuidado<br />em boas mãos.</span><span className="card-flower">✳</span></div><div className="digital-card-bottom"><div><small>ASSOCIADO(A)</small><b>{member.name.toUpperCase()}</b></div><span className="card-small-star">✦</span></div></div><div className="qr-panel"><div className="qr-panel-top"><div><Eyebrow>SEU CARTÃO DIGITAL</Eyebrow><h2>Mostre no parceiro.</h2></div><Status active={isEligible(member)}>{statusLabel(member.status)}</Status></div>{isEligible(member) ? <><div className="qr-wrap"><QrDisplay token={member.cardToken} /></div><p>Apresente este QR no balcão. O parceiro valida sua assinatura online e confere sua foto.</p></> : <div className="card-blocked"><LockKeyhole size={30} /><b>Benefícios indisponíveis</b><p>Procure a equipe RKMED para regularizar sua assinatura.</p></div>}<div className="qr-bottom"><span><ShieldCheck size={16} /> Confirmação segura no parceiro</span><span>RKMED GOLD</span></div></div></div><div className="member-side"><div className="savings-card"><div className="savings-icon"><TrendingUp size={21} /></div><span>VOCÊ JÁ ECONOMIZOU</span><strong>{brl(saved)}</strong><small>em {myPurchases.filter(p => !p.reversedAt).length} compras registradas</small><button onClick={() => go('/app/economia')}>Ver minha economia <ArrowUpRight size={17} /></button></div><div className="quick-block"><div className="small-section-head"><h3>Explore seus benefícios</h3><button onClick={() => go('/app/parceiros')}>Ver todos <ArrowRight size={15} /></button></div>{data.partners.slice(0, 3).map(p => <button className="quick-partner" key={p.id} onClick={() => go('/app/parceiros')}><PartnerLogo partner={p} /><span><b>{p.name}</b><small>{p.segment}</small></span><strong>{p.discount}%</strong></button>)}</div></div></div><div className="member-note"><div><Sparkles size={23} /></div><span><b>Seu cartão vai com você.</b><small>Depois de abrir este app uma vez, seus dados salvos ficam disponíveis mesmo sem internet.</small></span><ArrowRight size={20} /></div></>}{section === 'parceiros' && <><PanelHeader title="Parceiros que cuidam de você" subtitle="Encontre o lugar certo para cada momento." /><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="Buscar parceiro" value={query} onChange={e => setQuery(e.target.value)} /></div><div className="filter-chips">{['Todos', 'Laboratório', 'Academia', 'Suplementos'].map(t => <button key={t} className={filter === t ? 'active' : ''} onClick={() => setFilter(t)}>{t}</button>)}</div></div><div className="directory-grid">{available.map(p => <article className="directory-card" key={p.id}><div className={`directory-art tone-${p.tone}`}><PartnerLogo partner={p} /><span>{p.discount}% DE DESCONTO</span></div><div><small>{p.segment.toUpperCase()}</small><h3>{p.name}</h3><p><MapPin size={16} />{p.address}</p><div className="directory-foot"><Status active>Parceiro ativo</Status><ArrowUpRight size={18} /></div></div></article>)}</div></>}{section === 'economia' && <><PanelHeader title="Sua economia" subtitle="Cada escolha conta. Veja o que você já aproveitou." /><div className="stats-row"><div className="stat-large"><span>TOTAL ECONOMIZADO</span><strong>{brl(saved)}</strong><small>Desde que você começou com a RKMED</small></div><div className="stat-mini"><span>COMPRAS REGISTRADAS</span><strong>{myPurchases.filter(p => !p.reversedAt).length}</strong><small>Na sua jornada Gold</small></div><div className="stat-mini"><span>PARCEIROS VISITADOS</span><strong>{new Set(myPurchases.filter(p => !p.reversedAt).map(p => p.partnerId)).size}</strong><small>Mais opções para você</small></div></div><div className="surface-card"><div className="small-section-head"><h3>Histórico de compras</h3><small>Valores de demonstração</small></div>{myPurchases.length ? myPurchases.map(p => { const partner = data.partners.find(v => v.id === p.partnerId); return <div className="purchase-row" key={p.id}><span className="purchase-icon"><ShoppingBag size={19} /></span><div><b>{partner?.name ?? 'Parceiro'}</b><small>{shortDate(p.createdAt)} {p.reversedAt && '· Estornado'}</small></div><strong className={p.reversedAt ? 'muted' : ''}>{p.reversedAt ? brl(0) : `+ ${brl(p.discountCents)}`}</strong></div> }) : <p className="empty-copy">Sua primeira compra com desconto aparecerá aqui.</p>}</div></>}{section === 'conta' && <><PanelHeader title="Minha conta" subtitle="Seus dados e sua assinatura em um só lugar." /><div className="account-grid"><div className="surface-card account-profile"><Avatar member={member} size="large" /><h3>{member.name}</h3><Status active={isEligible(member)}>{statusLabel(member.status)}</Status><div className="account-fields"><div><span>E-mail verificado</span><b>{member.email}</b></div><div><span>WhatsApp verificado</span><b>••••{member.phone.slice(-4)}</b></div><div><span>CPF</span><b>{maskedCpf(member.cpf)}</b></div></div></div><div><div className="surface-card account-plan"><span className="eyebrow"><span className="eyebrow-line" /> SUA ASSINATURA</span><div><h3>Linha Gold</h3><Status active={isEligible(member)}>{statusLabel(member.status)}</Status></div><p>{brl(6960)} / mês · Próxima referência: {shortDate(member.paidThrough)}</p><button disabled={!online} onClick={() => setAccountAction('billing')}><CreditCard size={18} /> Gerenciar cobrança <ArrowUpRight size={18} /></button>{!online && <small>Disponível quando você se reconectar.</small>}<small className="demo-context">No protótipo, cobranças são apenas ilustrativas.</small></div><div className="surface-card support-card"><HelpCircle size={25} /><h3>Precisa de ajuda?</h3><p>Nossa equipe está aqui para você. Segunda a sexta, 8h às 18h; sábado, 8h às 12h.</p><button disabled={!online} onClick={() => setAccountAction('support')}>Falar com suporte <ArrowUpRight size={17} /></button>{!online && <small>Mensagens exigem conexão.</small>}<small className="demo-context">Canal real de suporte será configurado depois.</small></div></div></div></>}</div><nav className="mobile-bottom-nav">{tabs.map(t => <button key={t.to} className={path === t.to ? 'selected' : ''} onClick={() => go(t.to)}>{t.icon}<small>{t.label}</small></button>)}</nav>{accountAction && <MemberActionModal type={accountAction} member={member} close={() => setAccountAction(null)} notify={notify} />}</div></div>
}

function MemberActionModal({ type, member, close, notify }: { type: 'billing' | 'support'; member: Member; close: () => void; notify: (message: string) => void }) {
  const [value, setValue] = useState('')
  function submit(e: FormEvent) {
    e.preventDefault()
    if (!value.trim()) return
    notify(type === 'billing' ? `Cartão de demonstração terminado em ${onlyDigits(value).slice(-4)} salvo para esta sessão.` : 'Mensagem de suporte simulada. Nenhum contato real foi feito.')
    close()
  }
  return <div className="confirm-backdrop"><form className="confirm-card" onSubmit={submit}><button type="button" className="close-button" onClick={close} aria-label="Fechar"><X size={19} /></button><div className="confirm-icon">{type === 'billing' ? <CreditCard size={23} /> : <HelpCircle size={23} />}</div><h2>{type === 'billing' ? 'Gerenciar cobrança' : 'Falar com suporte'}</h2><p>{type === 'billing' ? `${member.name} · Linha Gold ${brl(6960)}/mês. Simule uma atualização de cartão. Nenhum dado de pagamento real é enviado.` : 'Escreva para a equipe RKMED nesta simulação. Nenhuma mensagem real será enviada.'}</p><label className="field-label">{type === 'billing' ? 'Últimos quatro números de cartão fictício' : 'Sua mensagem'}{type === 'billing' ? <input className="input" inputMode="numeric" maxLength={4} pattern="[0-9]{4}" required value={value} onChange={e => setValue(onlyDigits(e.target.value))} placeholder="4242" /> : <textarea className="input" required value={value} onChange={e => setValue(e.target.value)} placeholder="Como podemos ajudar?" />}</label><Button type="submit" className="full">{type === 'billing' ? 'Salvar atualização simulada' : 'Enviar mensagem simulada'}</Button><Button type="button" variant="ghost" className="full" onClick={close}>Cancelar</Button></form></div>
}

function CameraScanner({ onResult, onClose }: { onResult: (text: string) => void; onClose: () => void }) {
  const ref = useRef<HTMLVideoElement>(null)
  const [error, setError] = useState('')
  useEffect(() => {
    let active = true
    let controls: { stop: () => void } | undefined
    if (!ref.current) return
    void import('@zxing/browser').then(({ BrowserQRCodeReader }) => {
      if (!active || !ref.current) return
      const reader = new BrowserQRCodeReader()
      return reader.decodeFromVideoDevice(undefined, ref.current, (result) => {
        if (result && active) { active = false; controls?.stop(); onResult(result.getText()) }
      })
    }).then(c => { controls = c; if (!active) c?.stop() }).catch(() => setError('Não foi possível abrir a câmera. Confira a permissão ou digite o código do cartão.'))
    return () => { active = false; controls?.stop() }
  }, [onResult])
  return <div className="scanner-modal"><div className="scanner-card"><div className="scanner-head"><h2>Escanear QR do associado</h2><button onClick={onClose} aria-label="Fechar leitor"><X size={21} /></button></div><div className="scanner-viewport"><video ref={ref} playsInline muted /><span className="scan-corners" /><span className="scanner-line" /></div><p>Enquadre o QR do cartão digital na área indicada.</p>{error && <div className="inline-error"><CircleAlert size={16} />{error}</div>}<Button variant="outline" onClick={onClose}>Voltar e digitar código</Button></div></div>
}

function PartnerApp({ data, update, path, go, online, notify, logout }: AppShared & { path: string; logout: () => void }) {
  const [employeeCode, setEmployeeCode] = useState('')
  const [employeeError, setEmployeeError] = useState('')
  const [employee, setEmployee] = useState(() => sessionStorage.getItem('rkmed-demo-employee') ?? '')
  const [mode, setMode] = useState<'scan' | 'cpf'>('scan')
  const [search, setSearch] = useState('')
  const [scanOpen, setScanOpen] = useState(false)
  const [foundId, setFoundId] = useState('')
  const [error, setError] = useState('')
  const [amount, setAmount] = useState('')
  const [done, setDone] = useState<Purchase | null>(null)
  const [tab, setTab] = useState(path.endsWith('/historico') ? 'historico' : 'balcao')
  const partner = data.partners[0]
  const found = data.members.find(m => m.id === foundId)
  const grossCents = Math.round(Number(amount.replace(',', '.')) * 100)
  const calc = Number.isFinite(grossCents) && grossCents > 0 ? calculateDiscount(grossCents, partner.discount) : { discountCents: 0, finalCents: 0 }
  function selectEmployee(e: FormEvent) { e.preventDefault(); const match = data.employees.find(item => item.partnerId === partner.id && item.active && item.code === employeeCode); if (!match) return setEmployeeError('Código não encontrado na lista de funcionários ativos. Confira com o administrador.'); setEmployee(match.name); sessionStorage.setItem('rkmed-demo-employee', match.name); setEmployeeError('') }
  function resetFlow() { setSearch(''); setFoundId(''); setAmount(''); setError(''); setDone(null); setMode('scan') }
  function lookup(value: string, kind: 'scan' | 'cpf') {
    setError(''); setScanOpen(false)
    const m = data.members.find(member => kind === 'cpf' ? member.cpf === onlyDigits(value) : member.cardToken === value.trim())
    if (!m) { setFoundId(''); setError(kind === 'cpf' ? 'CPF não encontrado. Confira os 11 dígitos.' : 'QR não encontrado. Tente novamente ou busque pelo CPF.'); return }
    setFoundId(m.id); setSearch('')
    if (!isEligible(m)) setError('Benefício indisponível: assinatura bloqueada ou vencida. Oriente a pessoa a falar com a RKMED.')
  }
  function submitPurchase() {
    if (!online) return setError('É preciso estar online para registrar uma compra.')
    if (!found || !isEligible(found)) return setError('Este associado não está apto a usar o benefício.')
    if (!employee || !data.employees.some(item => item.partnerId === partner.id && item.active && item.name === employee)) return setError('Funcionário inativo ou não vinculado ao estabelecimento. Troque o funcionário.')
    if (!Number.isFinite(grossCents) || grossCents <= 0 || grossCents > 10000000) return setError('Informe um valor entre R$ 0,01 e R$ 100.000,00.')
    if (done) return
    const purchase: Purchase = { id: crypto.randomUUID(), memberId: found.id, partnerId: partner.id, employee, grossCents, ...calc, createdAt: new Date().toISOString() }
    update({ ...data, purchases: [purchase, ...data.purchases] }); setDone(purchase); notify('Compra registrada. O desconto já aparece na economia do associado.')
  }
  if (!employee) return <div className="partner-entry"><div className="partner-entry-card"><Brand dark /><div className="entry-symbol"><Fingerprint size={29} /></div><Eyebrow>INÍCIO DE TURNO</Eyebrow><h1>Quem está atendendo?</h1><p>Informe seu código uma vez neste turno. Os registros serão associados a você.</p><form onSubmit={selectEmployee}><label className="field-label">Código do funcionário<input className="input otp-input" type="password" inputMode="numeric" maxLength={4} placeholder="••••" value={employeeCode} onChange={e => setEmployeeCode(onlyDigits(e.target.value))} /></label>{employeeError && <div className="inline-error"><CircleAlert size={16} />{employeeError}</div>}<Button type="submit" className="full">Iniciar atendimento <ArrowRight size={17} /></Button></form><div className="demo-hint"><Sparkles size={16} /><span>Funcionária de demonstração: <b>Marina Costa</b> · Código inicial <b>2468</b></span></div><button className="text-link" onClick={logout}>Sair da conta do estabelecimento</button></div></div>
  return <div className="workspace partner-workspace"><aside className="workspace-sidebar"><Brand dark /><div className="workspace-identity"><PartnerLogo partner={partner} /><div><b>{partner.name}</b><small>Unidade Carpina</small></div></div><nav><button className={tab === 'balcao' ? 'selected' : ''} onClick={() => { setTab('balcao'); go('/parceiro') }}><ScanLine size={19} /> Balcão</button><button className={tab === 'historico' ? 'selected' : ''} onClick={() => { setTab('historico'); go('/parceiro/historico') }}><Receipt size={19} /> Histórico</button></nav><div className="workspace-sidebar-bottom"><button onClick={() => { setEmployee(''); sessionStorage.removeItem('rkmed-demo-employee'); resetFlow() }}><Users size={18} /> Trocar funcionário</button><button onClick={() => { sessionStorage.removeItem('rkmed-demo-employee'); logout() }}><LogOut size={18} /> Sair</button></div></aside><div className="workspace-content"><header className="workspace-topbar"><span><span className="workspace-breadcrumb">Parceiros</span> <ChevronRight size={14} /> {tab === 'historico' ? 'Histórico' : 'Balcão'}</span><div><Status active={online}>{online ? 'Operação online' : 'Sem conexão'}</Status><Avatar member={{ name: employee }} size="tiny" /><span>{employee}</span></div></header><main className="workspace-main">{tab === 'balcao' ? <><PanelHeader title="Bom atendimento começa aqui." subtitle="Valide o associado, confira a foto e registre a compra." side={<span className="today-chip"><CalendarDays size={16} /> {shortDate(new Date().toISOString())}</span>} /><div className="counter-layout"><section className="surface-card counter-flow"><div className="counter-step-head"><span>01</span><div><h2>Identifique o associado</h2><p>Leia o cartão digital ou busque pelo CPF.</p></div></div>{!done && <><div className="counter-tabs"><button className={mode === 'scan' ? 'active' : ''} onClick={() => { setMode('scan'); resetFlow() }}><QrCode size={19} /> Ler QR Code</button><button className={mode === 'cpf' ? 'active' : ''} onClick={() => { resetFlow(); setMode('cpf') }}><Search size={19} /> Buscar CPF</button></div><div className="counter-input">{mode === 'scan' ? <><button className="scan-trigger" disabled={!online} onClick={() => setScanOpen(true)}><span><ScanLine size={34} /></span><b>Abrir câmera</b><small>Escaneie o QR exibido no celular do associado</small></button><div className="input-with-button"><input className="input" value={search} onChange={e => setSearch(e.target.value)} placeholder="Ou cole o código do cartão" /><Button variant="secondary" disabled={!online} onClick={() => lookup(search, 'scan')}>Buscar</Button></div></> : <><p>Para o associado sem celular, digite o CPF e confira a foto pessoalmente.</p><div className="input-with-button"><input className="input" value={search} onChange={e => setSearch(e.target.value)} inputMode="numeric" maxLength={14} placeholder="000.000.000-00" /><Button variant="secondary" disabled={!online} onClick={() => lookup(search, 'cpf')}>Buscar</Button></div><small>O CPF completo não aparece nos resultados do painel.</small></>}</div></>}{error && <div className="inline-error"><CircleAlert size={17} />{error}</div>}{found && !done && <><div className={`identity-result ${isEligible(found) ? '' : 'identity-blocked'}`}><Avatar member={found} size="large" /><div><span>ASSOCIADO ENCONTRADO</span><h3>{found.name}</h3><small>CPF {maskedCpf(found.cpf)}</small><Status active={isEligible(found)}>{isEligible(found) ? 'Benefício disponível' : 'Benefício indisponível'}</Status></div></div><div className="confirm-photo"><ShieldCheck size={20} /><span>Confira se a pessoa à sua frente corresponde à foto do cadastro. A detecção de rosto no cadastro não faz reconhecimento de identidade.</span></div></>}{done && <div className="purchase-success"><span><Check size={34} /></span><h2>Compra registrada!</h2><p>O associado economizou <b>{brl(done.discountCents)}</b> nesta compra.</p><Button onClick={resetFlow}>Registrar outra compra <Plus size={17} /></Button></div>}</section><aside className="counter-right"><div className="surface-card purchase-form"><div className="counter-step-head"><span>02</span><div><h2>Registre a compra</h2><p>O desconto é calculado automaticamente.</p></div></div><label className="field-label">Valor bruto da compra (R$)<div className="currency-input"><span>R$</span><input inputMode="decimal" placeholder="0,00" value={amount} onChange={e => setAmount(e.target.value)} disabled={!found || !isEligible(found) || !!done} /></div></label><div className="discount-breakdown"><div><span>Valor da compra</span><b>{brl(grossCents > 0 ? grossCents : 0)}</b></div><div><span>Desconto RKMED ({partner.discount}%)</span><b className="discount-value">− {brl(calc.discountCents)}</b></div><div className="total"><span>Valor a cobrar</span><strong>{brl(calc.finalCents)}</strong></div></div><Button className="full" disabled={!online || !found || !isEligible(found) || !amount || !!done} onClick={submitPurchase}>Confirmar registro <ArrowRight size={17} /></Button><p className="tiny-note">O pagamento acontece diretamente entre associado e parceiro.</p></div><div className="tip-card"><Sparkles size={22} /><b>Atendimento em menos de 90 segundos.</b><p>Conferência visual + registro simples para não interromper o cuidado.</p></div></aside></div></> : <><PanelHeader title="Histórico do estabelecimento" subtitle="Registros recentes da unidade, com economia de cada associado." /><div className="surface-card table-card"><table><thead><tr><th>Associado</th><th>Data</th><th>Funcionário</th><th>Compra</th><th>Desconto</th><th>Status</th></tr></thead><tbody>{data.purchases.filter(p => p.partnerId === partner.id).map(p => { const m = data.members.find(x => x.id === p.memberId); return <tr key={p.id}><td>{m?.name ?? 'Associado'}</td><td>{shortDate(p.createdAt)}</td><td>{p.employee}</td><td>{brl(p.grossCents)}</td><td>{brl(p.discountCents)}</td><td><Status active={!p.reversedAt}>{p.reversedAt ? 'Estornado' : 'Registrado'}</Status></td></tr> })}</tbody></table></div></>}</main></div>{scanOpen && <CameraScanner onResult={value => lookup(value, 'scan')} onClose={() => setScanOpen(false)} />}</div>
}

function AdminApp({ data, update, session, path, go, online, notify, logout }: AppShared & { path: string; logout: () => void }) {
  const [query, setQuery] = useState('')
  const [tab, setTab] = useState(path.split('/')[2] ?? '')
  const [selected, setSelected] = useState<string | null>(null)
  const [reason, setReason] = useState('')
  const [confirm, setConfirm] = useState<'link' | 'retry' | null>(null)
  
  const [actionBusy, setActionBusy] = useState(false)
  const viewer = session?.role === 'viewer'
  const activeCount = data.members.filter(isEligible).length
  const totalSavings = data.purchases.filter(p => !p.reversedAt).reduce((sum, p) => sum + p.discountCents, 0)
  const overdue = data.members.filter(m => !isEligible(m))
  function choose(t: string) { setTab(t); go(t ? `/admin/${t}` : '/admin') }
  function reverse(p: Purchase) {
    if (viewer || !online || !reason.trim() || p.reversedAt) return
    update({ ...data, purchases: data.purchases.map(x => x.id === p.id ? { ...x, reversedAt: new Date().toISOString(), reversedBy: 'Admin RKMED', reversalReason: reason.trim() } : x) }); setSelected(null); setReason(''); notify('Registro estornado. A economia do associado foi atualizada.')
  }
  function collect() {
    if (!confirm || !selected || viewer || !online || actionBusy) return
    setActionBusy(true)
    const memberId = selected
    const action = confirm
    const invoiceRef = `demo-invoice-${memberId}`
    const duplicate = data.collectionLogs.some(item => item.invoiceRef === invoiceRef && item.action === action && Date.now() - new Date(item.createdAt).getTime() < 30000)
    if (duplicate) { setActionBusy(false); setConfirm(null); setSelected(null); notify('Ação já registrada nos últimos 30 segundos. Confira o histórico.'); return }
    window.setTimeout(() => {
      update({ ...data, collectionLogs: [{ id: crypto.randomUUID(), memberId, action, invoiceRef, actor: 'Equipe RK', createdAt: new Date().toISOString() }, ...data.collectionLogs] })
      notify(action === 'link' ? 'Link Stripe de demonstração registrado como enviado.' : 'Retentativa da fatura existente registrada em modo de demonstração.')
      setActionBusy(false); setConfirm(null); setSelected(null)
    }, 650)
  }
  return <div className="workspace admin-workspace"><aside className="workspace-sidebar"><Brand dark /><div className="workspace-label">PAINEL DE GESTÃO</div><nav>{[{ key: '', icon: <LayoutDashboard size={19} />, label: 'Visão geral' }, { key: 'associados', icon: <Users size={19} />, label: 'Associados' }, { key: 'compras', icon: <Receipt size={19} />, label: 'Compras' }, { key: 'cobrancas', icon: <CreditCard size={19} />, label: 'Cobranças', badge: overdue.length }, { key: 'parceiros', icon: <MapPin size={19} />, label: 'Parceiros' }, { key: 'equipe', icon: <UserRound size={19} />, label: 'Equipe' }].map(item => <button key={item.key} className={tab === item.key ? 'selected' : ''} onClick={() => choose(item.key)}>{item.icon} {item.label}{item.badge ? <span className="sidebar-count">{item.badge}</span> : null}</button>)}</nav><div className="workspace-sidebar-bottom"><div className="admin-user"><Avatar member={{ name: viewer ? 'Diretoria RK' : 'Equipe RK' }} size="tiny" /><span><b>{viewer ? 'Diretoria RK' : 'Equipe RK'}</b><small>{viewer ? 'Visualização' : 'Administrador'}</small></span></div><button onClick={logout}><LogOut size={18} /> Sair</button></div></aside><div className="workspace-content"><header className="workspace-topbar"><span><span className="workspace-breadcrumb">RKMED</span> <ChevronRight size={14} /> {tab || 'Visão geral'}</span><div><span className="workspace-date">{shortDate(new Date().toISOString())}</span><button className="icon-button" aria-label="Notificações" onClick={() => choose('cobrancas')}><Bell size={18} /><i /></button><Avatar member={{ name: viewer ? 'Diretoria RK' : 'Equipe RK' }} size="tiny" /></div></header><main className="workspace-main">{!tab && <><PanelHeader title="Um olhar sobre o cuidado." subtitle="Acompanhe o clube e cada detalhe que faz diferença." side={<span className="today-chip"><Activity size={16} /> Dados de demonstração</span>} /><div className="admin-stats"><div className="admin-stat"><span className="stat-top"><span>ASSOCIADOS ATIVOS</span><Users size={19} /></span><strong>{activeCount.toString().padStart(2, '0')}</strong><small><TrendingUp size={14} /> Assinaturas disponíveis</small></div><div className="admin-stat"><span className="stat-top"><span>COMPRAS REGISTRADAS</span><ShoppingBag size={19} /></span><strong>{data.purchases.filter(p => !p.reversedAt).length.toString().padStart(2, '0')}</strong><small><ArrowUpRight size={14} /> Em parceiros credenciados</small></div><div className="admin-stat"><span className="stat-top"><span>ECONOMIA GERADA</span><Wallet size={19} /></span><strong>{brl(totalSavings)}</strong><small><Sparkles size={14} /> Para os associados</small></div><div className="admin-stat alert-stat"><span className="stat-top"><span>ATENÇÃO NECESSÁRIA</span><CircleAlert size={19} /></span><strong>{overdue.length.toString().padStart(2, '0')}</strong><small>Assinatura pendente</small></div></div><div className="admin-dashboard-grid"><div className="surface-card"><div className="small-section-head"><h3>Últimas compras</h3><button onClick={() => choose('compras')}>Ver todas <ArrowRight size={16} /></button></div>{data.purchases.slice(0, 4).map(p => { const m = data.members.find(x => x.id === p.memberId); const partner = data.partners.find(x => x.id === p.partnerId); return <div className="dash-row" key={p.id}><span className="purchase-icon"><ShoppingBag size={18} /></span><span><b>{m?.name ?? 'Associado'}</b><small>{partner?.name} · {shortDate(p.createdAt)}</small></span><strong>{brl(p.grossCents)}</strong></div> })}</div><div className="surface-card attention-card"><div className="small-section-head"><h3>Precisam de atenção</h3><button onClick={() => choose('cobrancas')}>Ver cobranças <ArrowRight size={16} /></button></div>{overdue.map(m => <div className="attention-row" key={m.id}><Avatar member={m} size="tiny" /><span><b>{m.name}</b><small>Assinatura bloqueada</small></span><CircleAlert size={18} /></div>)}<div className="attention-note"><Heart size={17} /> Um contato atencioso faz a diferença.</div></div></div></>}{tab === 'associados' && <><PanelHeader title="Associados" subtitle="Pessoas no centro de cada decisão." /><div className="toolbar"><div className="search-box"><Search size={18} /><input placeholder="Buscar nome ou CPF exato" value={query} onChange={e => setQuery(e.target.value)} /></div><span className="today-chip">{data.members.length} associados</span></div><div className="surface-card table-card"><table><thead><tr><th>Associado</th><th>CPF protegido</th><th>Assinatura</th><th>Economia</th><th>Adesão</th></tr></thead><tbody>{data.members.filter(m => !query || m.name.toLowerCase().includes(query.toLowerCase()) || m.cpf === onlyDigits(query)).map(m => <tr key={m.id}><td><span className="table-person"><Avatar member={m} size="tiny" /><span><b>{m.name}</b><small>{m.email}</small></span></span></td><td>{maskedCpf(m.cpf)}</td><td><Status active={isEligible(m)}>{statusLabel(m.status)}</Status></td><td>{brl(memberSavings(m.id, data.purchases))}</td><td>{shortDate(m.joinedAt)}</td></tr>)}</tbody></table></div><p className="demo-context">Este protótipo mantém CPF em dados locais de demonstração para simular a busca. O produto real retornará apenas CPF mascarado ao navegador.</p></>}{tab === 'compras' && <><PanelHeader title="Compras registradas" subtitle="Veja os benefícios utilizados e corrija registros quando necessário." /><div className="surface-card table-card"><table><thead><tr><th>Associado</th><th>Parceiro</th><th>Data</th><th>Valor</th><th>Economia</th><th>Status</th>{!viewer && <th />}</tr></thead><tbody>{data.purchases.map(p => { const m = data.members.find(x => x.id === p.memberId); const partner = data.partners.find(x => x.id === p.partnerId); return <tr key={p.id}><td>{m?.name}</td><td>{partner?.name}</td><td>{shortDate(p.createdAt)}</td><td>{brl(p.grossCents)}</td><td>{brl(p.discountCents)}</td><td><Status active={!p.reversedAt}>{p.reversedAt ? 'Estornado' : 'Registrado'}</Status></td>{!viewer && <td><button className="table-action" disabled={!!p.reversedAt || !online} onClick={() => setSelected(p.id)}>Estornar</button></td>}</tr> })}</tbody></table></div>{selected && !confirm && <div className="confirm-backdrop"><div className="confirm-card"><button className="close-button" onClick={() => { setSelected(null); setReason('') }}><X size={19} /></button><div className="confirm-icon"><Receipt size={23} /></div><h2>Estornar compra?</h2><p>O registro original ficará no histórico. A economia do associado será atualizada.</p><label className="field-label">Motivo do estorno<textarea className="input" value={reason} onChange={e => setReason(e.target.value)} placeholder="Descreva o motivo" /></label><Button disabled={!reason.trim() || !online} onClick={() => { const p = data.purchases.find(x => x.id === selected); if (p) reverse(p) }} className="full">Confirmar estorno</Button><Button variant="ghost" className="full" onClick={() => setSelected(null)}>Cancelar</Button></div></div>}</>}{tab === 'cobrancas' && <><PanelHeader title="Cobranças e suporte" subtitle="Cuide dos associados com pendências e acompanhe cada ação." /><div className="collections-intro"><div><CircleAlert size={22} /></div><span><b>{overdue.length} associado{overdue.length === 1 ? '' : 's'} precisa{overdue.length === 1 ? '' : 'm'} de atenção</b><small>Benefícios indisponíveis desde a falha no pagamento. O parceiro vê essa situação ao validar o cartão.</small></span></div><div className="surface-card table-card"><table><thead><tr><th>Associado</th><th>CPF</th><th>Situação</th><th>Mensalidade</th><th>Última tentativa</th>{!viewer && <th>Ações</th>}</tr></thead><tbody>{overdue.map(m => <tr key={m.id}><td><span className="table-person"><Avatar member={m} size="tiny" /><span><b>{m.name}</b><small>{m.email}</small></span></span></td><td>{maskedCpf(m.cpf)}</td><td><Status active={false}>Pagamento pendente</Status></td><td>{brl(6960)}</td><td>{shortDate(m.paidThrough)}</td>{!viewer && <td><div className="row-actions"><button disabled={!online} onClick={() => { setSelected(m.id); setConfirm('link') }}>Enviar link</button><button disabled={!online} onClick={() => { setSelected(m.id); setConfirm('retry') }}>Retentar fatura</button></div></td>}</tr>)}</tbody></table></div><div className="surface-card collection-history"><div className="small-section-head"><h3>Histórico de ações</h3><small>Simulação local auditável</small></div>{data.collectionLogs.length ? data.collectionLogs.map(item => <div className="dash-row" key={item.id}><span className="purchase-icon"><CreditCard size={18} /></span><span><b>{item.action === 'link' ? 'Link enviado' : 'Retentativa solicitada'} · {data.members.find(m => m.id === item.memberId)?.name}</b><small>{item.actor} · {shortDate(item.createdAt)} · {item.invoiceRef}</small></span></div>) : <p className="empty-copy">Nenhuma ação de cobrança registrada.</p>}</div>{confirm && selected && <div className="confirm-backdrop"><div className="confirm-card"><button className="close-button" onClick={() => { setConfirm(null); setSelected(null) }}><X size={19} /></button><div className="confirm-icon"><CreditCard size={23} /></div><h2>{confirm === 'link' ? 'Enviar link de cobrança?' : 'Retentar fatura existente?'}</h2><p>{data.members.find(m => m.id === selected)?.name} · Mensalidade {brl(6960)}. Esta é uma ação simulada com confirmação e sem cobrança real.</p><div className="demo-hint"><ShieldCheck size={16} /><span>A operação real deverá auditar a ação e proteger contra cobranças duplicadas.</span></div><Button className="full" disabled={!online || actionBusy} onClick={collect}>{actionBusy ? 'Registrando...' : 'Confirmar ação'}</Button><Button className="full" variant="ghost" onClick={() => { setConfirm(null); setSelected(null) }}>Cancelar</Button></div></div>}</>}{tab === 'parceiros' && <><PanelHeader title="Parceiros credenciados" subtitle="Uma rede selecionada para cuidar melhor." /><div className="directory-grid">{data.partners.map(p => <div className="directory-card" key={p.id}><div className={`directory-art tone-${p.tone}`}><PartnerLogo partner={p} /><span>{p.discount}% DE DESCONTO</span></div><div><small>{p.segment.toUpperCase()}</small><h3>{p.name}</h3><p><MapPin size={16} /> {p.address}</p><Status active>Ativo</Status></div></div>)}</div></>}{tab === 'equipe' && <><PanelHeader title="Equipe do parceiro" subtitle="Funcionários autorizados para registrar compras." /><div className="surface-card team-card"><div className="small-section-head"><h3>Laboratório Vida</h3><Status active>{data.employees.filter(item => item.partnerId === 'vida' && item.active).length} funcionário(s) ativo(s)</Status></div>{data.employees.filter(item => item.partnerId === 'vida').map(item => <div className="team-person" key={item.id}><Avatar member={{ name: item.name }} /><span><b>{item.name}</b><small>Código do turno: {viewer ? '••••' : item.code}</small></span><Status active={item.active}>{item.active ? 'Ativa' : 'Inativa'}</Status>{!viewer && <button className="table-action" disabled={!online} onClick={() => { update({ ...data, employees: data.employees.map(emp => emp.id === item.id ? { ...emp, active: !emp.active } : emp) }); notify(item.active ? 'Funcionário desativado.' : 'Funcionário ativado.') }}>{item.active ? 'Desativar' : 'Ativar'}</button>}</div>)}{!viewer && <label className="field-label">Código da funcionária<input className="input" value={data.employees[0]?.code ?? ''} maxLength={4} inputMode="numeric" disabled={!online} onChange={e => update({ ...data, employees: data.employees.map(emp => emp.id === 'employee-marina' ? { ...emp, code: onlyDigits(e.target.value) } : emp) })} /><small>Uma alteração exige o novo código no próximo início de turno.</small></label>}</div></>}</main></div></div>
}

function LegalPage({ type, go }: { type: string; go: (p: string) => void }) { return <div className="legal-page shell"><header className="simple-header"><button className="brand-button" onClick={() => go('/')}><Brand /></button><button className="back-link" onClick={() => go('/cadastro')}><ArrowLeft size={16} /> Cadastro</button></header><div className="legal-card"><Eyebrow>DOCUMENTO DE TESTE</Eyebrow><h1>{type === 'termos' ? 'Termos de uso' : 'Aviso de privacidade'}</h1><div className="legal-warning">{LEGAL_WARNING}</div>{type === 'termos' ? <><p>Este protótipo demonstra um clube de benefícios para maiores de 18 anos. A mensalidade ilustrativa é {brl(6960)}. O associado paga suas compras diretamente ao parceiro credenciado.</p><p>O cartão digital pode ser exibido offline. A validação da assinatura e o registro de compra exigem que o parceiro esteja online. Falha de pagamento remove o acesso ao benefício imediatamente.</p><p>Todo cadastro, pagamento e aceite nesta versão são simulados. O texto definitivo depende de revisão jurídica.</p></> : <><p>O protótipo armazena dados fictícios no navegador para demonstrar cadastro, cartão, compras e economia. A foto é analisada apenas para detectar a presença de um rosto.</p><p>O CPF é mostrado mascarado nas telas. A versão demonstrativa usa armazenamento local e não deve receber dados reais. Dados salvos podem permanecer offline até serem apagados pelo navegador ou pelo usuário.</p><p>Este texto deverá ser substituído e aprovado antes do uso em produção.</p></>}</div></div> }

export default App
